     7	const bindHandlerToKeydownEvent: BindHandlerToKeydownEvent = (getDisplayName, eventHandlers, keyCommandEvent, event) => {
     8	    const eventModifiers = getKeyEventModifiers(keyCommandEvent);
     9	    const displayName = getDisplayName(keyCommandEvent.input, eventModifiers);
