    17	    Object.values(eventHandlers[displayName]).every((callback) => {
    18	        // Determine if the event should bubble before executing the callback (which may have side-effects)
    19	        let shouldBubble: boolean | (() => void) | void = callback.shouldBubble || false;
    20	        if (typeof callback.shouldBubble === 'function') {
    21	            shouldBubble = callback.shouldBubble();
    22	        }
    23	
    24	        if (typeof callback.callback === 'function') {
    25	            callback.callback(event);
    26	        }
    27	
    28	        // If the event should not bubble, short-circuit the loop
    29	        return shouldBubble;
    30	    });
