   320	                // This is because when wrapping whole screen the screen was freezing when changing Tabs.
   321	                keyboardVerticalOffset={variables.contentHeaderHeight + (insets?.top ?? 0) + variables.tabSelectorButtonHeight + variables.tabSelectorButtonPadding}
   322	            >
   323	                <SelectionList<OptionsListUtils.Option & ListItem>
   324	                    ref={selectionListRef}
   325	                    ListItem={UserListItem}
   326	                    sections={areOptionsInitialized ? sections : CONST.EMPTY_ARRAY}
   327	                    textInputValue={searchTerm}
   328	                    textInputHint={isOffline ? `${translate('common.youAppearToBeOffline')} ${translate('search.resultsAreLimited')}` : ''}
   329	                    onChangeText={setSearchTerm}
   330	                    textInputLabel={translate('selectionList.nameEmailOrPhoneNumber')}
   331	                    headerMessage={headerMessage}
   332	                    onSelectRow={createChat}
   333	                    shouldSingleExecuteRowSelect
   334	                    onConfirm={(e, option) => (selectedOptions.length > 0 ? createGroup() : createChat(option))}
   335	                    rightHandSideComponent={itemRightSideComponent}
   336	                    footerContent={footerContent}
   337	                    showLoadingPlaceholder={!areOptionsInitialized}
   338	                    shouldPreventDefaultFocusOnSelectRow={!DeviceCapabilities.canUseTouchScreen()}
   339	                    isLoadingNewOptions={!!isSearchingForReports}
   340	                    initiallyFocusedOptionKey={firstKeyForList}
   341	                    shouldTextInputInterceptSwipe
   342	                />
   343	                {isSmallScreenWidth && (
   344	                    <>
   345	                        <OfflineIndicator />
   346	                        <ImportedStateIndicator />
   347	                    </>
   348	                )}
   349	            </KeyboardAvoidingView>
   350	        </ScreenWrapper>
   351	    );
   352	}
